import com.cowave.search.client.keyword_analyzer.dto.KeywordAnalysisRequest
import com.cowave.search.client.keyword_analyzer.dto.KeywordAnalysisResponse
import com.cowave.shared.utils.logger
import org.springframework.beans.factory.annotation.Qualifier
import org.springframework.stereotype.Component
import org.springframework.web.client.RestClient

@Component
class KeywordAnalysisClient(
    @Qualifier("keywordAnalysisRestClient") private val restClient: RestClient,
) {
    fun tokenizeKeyword(
        keyword: String,
        filterStopword: Boolean,
        isExpandSynonym: Boolean,
    ): KeywordAnalysisResponse? {
        val requestBody =
            KeywordAnalysisRequest(
                text = keyword,
                synonym = isExpandSynonym,
                stopWord = filterStopword,
            )

        return try {
            restClient
                .post()
                .uri("/_analysis-product-name/search-keyword")
                .body(requestBody)
                .retrieve()
                .body(KeywordAnalysisResponse::class.java)
        } catch (e: Exception) {
            log.error(e) { "HTTP Keyword Analysis Exception: ${e.message}" }
            null
        }
    }

    companion object {
        private val log by logger()
    }
}"}

