import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.http.MediaType
import org.springframework.http.client.SimpleClientHttpRequestFactory
import org.springframework.web.client.RestClient
import java.net.HttpURLConnection
import java.security.SecureRandom
import java.security.cert.X509Certificate
import javax.net.ssl.*

@Configuration
class KeywordAnalysisConfig {
    @Bean("keywordAnalysisRestClient")
    fun keywordAnalysisRestClient(properties: KeywordAnalysisClientProperties): RestClient {
        val trustAllCerts =
            arrayOf<TrustManager>(
                object : X509TrustManager {
                    override fun getAcceptedIssuers(): Array<X509Certificate>? = null

                    override fun checkClientTrusted(
                        certs: Array<X509Certificate>,
                        authType: String,
                    ) {}

                    override fun checkServerTrusted(
                        certs: Array<X509Certificate>,
                        authType: String,
                    ) {}
                },
            )

        val sslContext = SSLContext.getInstance("TLS")
        sslContext.init(null, trustAllCerts, SecureRandom())

        val requestFactory =
            object : SimpleClientHttpRequestFactory() {
                override fun prepareConnection(
                    connection: HttpURLConnection,
                    httpMethod: String,
                ) {
                    if (connection is HttpsURLConnection) {
                        connection.sslSocketFactory = sslContext.socketFactory
                        connection.hostnameVerifier = HostnameVerifier { _, _ -> true }
                    }
                    super.prepareConnection(connection, httpMethod)
                }
            }.apply {
                setConnectTimeout(properties.connectionTimeout)
                setReadTimeout(properties.socketTimeout)
            }

        return RestClient
            .builder()
            .baseUrl(properties.url)
            .requestFactory(requestFactory)
            .defaultHeaders { headers ->
                headers.contentType = MediaType.APPLICATION_JSON
                headers.set("Authorization", "ApiKey ${properties.apiKey}")
            }.build()
    }
}"}

