    private val indexName: IndexNameProperties,
) : ProductIndexRepository {
    private val logger by logger()

    override fun bulk(documents: List<IndexDocument<ProductDocument>>): IndexResult {
        if (documents.isEmpty()) {
            return IndexResult.empty()
