import com.commerce.proxy.shopping.catalog.infrastructure.consumer.dto.Catalog
import com.commerce.proxy.shopping.catalog.infrastructure.consumer.dto.CatalogCdcEnvelope
import com.commerce.proxy.shopping.catalog.infrastructure.consumer.dto.CatalogCdcKey
import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.Product
import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.ProductCdcEnvelope
import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.ProductCdcKey
import com.cowave.search.domain.index.dto.ChangedCatalogDocument
import com.cowave.search.domain.index.dto.ChangedData
import com.cowave.search.domain.index.dto.ChangedProductDocument
import com.cowave.search.domain.index.enums.Operation
import org.apache.avro.specific.SpecificRecord
import org.apache.kafka.clients.consumer.ConsumerRecord
import com.commerce.proxy.shopping.catalog.infrastructure.consumer.dto.ChannelData as CdcEnvelopCatalogChannelData
import com.commerce.proxy.shopping.product.infrastructure.consumer.dto.ChannelData as CdcEnvelopProductChannelData

fun ConsumerRecord<SpecificRecord, SpecificRecord>.toChangedCatalogData(): ChangedData<ChangedCatalogDocument> {
    val key = this.key() as CatalogCdcKey
    val value = this.value() as CatalogCdcEnvelope

    return ChangedData(
        id = (key.`id$1` ?: value.after?.`id$1` ?: value.before?.`id$1`!!).toString(),
        op = convertOp(value.op),
        beforeData = value.before?.toChangedCatalogDocument(),
        afterData = value.after?.toChangedCatalogDocument(),
        partition = this.partition(),
        offset = this.offset(),
    )
}

fun ConsumerRecord<SpecificRecord, SpecificRecord>.toChangedProductData(): ChangedData<ChangedProductDocument> {
    val key = this.key() as ProductCdcKey
    val value = this.value() as ProductCdcEnvelope
    return ChangedData(
        id = (key.`id$1` ?: value.after?.`id$1` ?: value.before?.`id$1`!!).toString(),
        op = convertOp(value.op),
        beforeData = value.before?.toChangedProductDocument(),
        afterData = value.after?.toChangedProductDocument(),
        partition = this.partition(),
        offset = this.offset(),
    )
}

private fun convertOp(value: String): Operation =
    when (value) {
        "c" -> Operation.CREATE
        "u" -> Operation.UPDATE
        "d" -> Operation.DELETE
        else -> throw IllegalArgumentException("Unknown operation type.")
    }

private fun Catalog.toChangedCatalogDocument() =
    with(this) {
        ChangedCatalogDocument(
            id = `id$1`.toString(),
            name = name,
            categoryId = categoryId,
            brandId = brandId,
            manufacturerId = manufacturerId,
            isAutoCreate = isAutoCreate,
            isDisplayed = isDisplayed,
            isPriceLocked = isPriceLocked,
            registeredAt = registeredAt,
            updatedAt = updatedAt,
            createdAt = createdAt,
            channelDatas =
                ChangedCatalogDocument.ChannelDatas(
                    danawa = channelDatas["DANAWA"]?.run { this.toCatalogChannelData() },
                    enuri = channelDatas["ENURI"]?.run { this.toCatalogChannelData() },
                ),
        )
    }

private fun CdcEnvelopCatalogChannelData.toCatalogChannelData(): ChangedCatalogDocument.ChannelDatas.ChannelData =
    ChangedCatalogDocument.ChannelDatas.ChannelData(
        catalogStatus = catalogStatus,
        price =
            price?.let {
                ChangedCatalogDocument.ChannelDatas.ChannelData.Price(
                    lowestPrice = it.lowestPrice,
                    averagePrice = it.averagePrice,
                    mobileLowestPrice = it.mobileLowestPrice,
                    deliveryChargeSumLowestPrice = it.deliveryChargeSumLowestPrice,
                )
            },
        promotion =
            promotion?.let {
                ChangedCatalogDocument.ChannelDatas.ChannelData.Promotion(
                    lowestPrice = it.lowestPrice,
                )
            },
        memberShipPrice =
            memberShipPrice?.let {
                ChangedCatalogDocument.ChannelDatas.ChannelData.MembershipPrice(
                    lowestPrice = it.lowestPrice,
                    deliveryChargeSumLowestPrice = it.deliveryChargeSumLowestPrice,
                    unitPrice = it.unitPrice,
                    deliveryChargeSumUnitPrice = it.deliveryChargeSumUnitPrice,
                )
            },
        score =
            score?.let {
                ChangedCatalogDocument.ChannelDatas.ChannelData.Score(
                    popularityScore = it.popularityScore,
                )
            },
    )

private fun Product.toChangedProductDocument() =
    with(this) {
        ChangedProductDocument(
            id = `id$1`.toString(),
            name = name,
            categoryId = categoryId, // Note. mallCategoryId와 매핑되어 있다
            brandId = brandId, // Note. 분류기에서 아직 값을 처리하지 않아 null로 오는 중
            mallBrandName = mallBrandName, // Note. brandName mallBrandName 서로 개념이 다름
            manufacturerId = manufacturerId, // Note. 분류기에서 아직 값을 처리하지 않아 null로 오는 중
            mallManufacturerName = mallManufacturerName, // Note. manufacturerName와 mallManufactureName는 서로 개념이 다름
            productStatus = collectedStatus,
            mallId = mallId,
            mallProductId = mallProductId, // Note. 레거시에서는 mallProductId(협력사 상품코드)로 검색
            manufactureDefineNumber = manufactureDefineNumber,
            hasStock = hasStock,
            // Note. source = {MANUAL_ADMIN, VECTOR_APPROVED, VECTOR_AUTO, NONE}
            isCatalogMatch = catalogMatchings?.any { it.source != "NONE" } ?: false,
            isAiMatch =
                catalogMatchings?.any {
                    it.source in listOf("VECTOR_APPROVED", "VECTOR_AUTO")
                } ?: false,
            isOfficialWarranty = warrantyAlliance != null,
            isBrandCertification = brandAlliance != null,
            isUsedProduct = isUsedProduct,
            isRefurbished = isRefurbished,
            collectedAt = collectedAt,
            updatedAt = updatedAt,
            createdAt = createdAt,
            channelDatas =
                ChangedProductDocument.ChannelDatas(
                    danawa = channelDatas["DANAWA"]?.run { this.toInternalProductChannelData() },
                    enuri = channelDatas["ENURI"]?.run { this.toInternalProductChannelData() },
                ),
        )
    }

private fun CdcEnvelopProductChannelData.toInternalProductChannelData(): ChangedProductDocument.ChannelDatas.ChannelData =
    ChangedProductDocument.ChannelDatas.ChannelData(
        price =
            price?.let {
                ChangedProductDocument.ChannelDatas.ChannelData.Price(
                    pc = it.pc,
                    mobile = it.mobile,
                    membershipPrice = it.membershipPrice,
                )
            },
        benefit =
            benefit?.let {
                ChangedProductDocument.ChannelDatas.ChannelData.Benefit(
                    point = it.point,
                    coupon = it.coupon,
                    interestFree = it.interestFree,
                    gift = it.gift,
                    hasCouponDownload = it.hasCouponDownload,
                )
            },
        promotions =
            promotions?.map { promo ->
                ChangedProductDocument.ChannelDatas.ChannelData.Promotion(
                    type = promo.type,
                    name = promo.name,
                    price = promo.price,
                )
            },
    )"}

