### 6.2 역싱크 추가 후 흐름

```kotlin
// application/index/src/main/kotlin/.../service/ProductApplicationService.kt
@Service
class ProductIndexApplicationService(
    private val productIndexRepository: ProductIndexRepository,
    private val productAssembleService: ProductAssembleService,
    private val legacySyncService: LegacySyncService,  // [추가]
) {
    private val logger by logger()

    fun indexProducts(changedData: List<ChangedData<ChangedProductDocument>>): IndexResult {
        val indexDocuments = changedData
            .let(ProductMergeStrategy::merge)
            .let { productAssembleService.assemble(it) }
            .filter(ProductEvaluator::evaluate)

        // 1. 현재 ES 색인 (기존)
        val indexResult = productIndexRepository.bulk(indexDocuments)

        // 2. 레거시 ES 역싱크 (추가) - 비동기 or 동기 선택 가능
        runCatching {
            legacySyncService.syncToLegacy(changedData)
        }.onFailure { ex ->
            logger.error(ex) { "레거시 ES 역싱크 실패" }
            // 실패해도 메인 색인은 성공으로 처리
        }

        return indexResult
    }
}
```

### 6.3 LegacySyncService 구현

```kotlin
// application/index/src/main/kotlin/.../service/LegacySyncService.kt
@Service
class LegacySyncService(
    private val legacySyncPort: LegacySyncPort,
    private val legacyRequestMapper: LegacyRequestMapper,
) {
    private val logger by logger()

    fun syncToLegacy(changedData: List<ChangedData<ChangedProductDocument>>) {
        // 1. 링크/미링크 상품 분류
        val (linkedProducts, unlinkedProducts) = changedData.partition { 
            it.afterData?.isCatalogMatch ?: it.beforeData?.isCatalogMatch ?: false 
        }

        // 2. 레거시 요청 포맷으로 변환
        val requests = buildList {
            if (linkedProducts.isNotEmpty()) {
                add(legacyRequestMapper.toLinkedProductRequest(linkedProducts))
            }
            if (unlinkedProducts.isNotEmpty()) {
                add(legacyRequestMapper.toUnlinkedProductRequest(unlinkedProducts))
            }
        }

        // 3. 레거시 API 호출
        if (requests.isNotEmpty()) {
            val result = legacySyncPort.sync(requests)
            logger.info { "레거시 싱크 완료: success=${result.successCount}, failure=${result.failureCount}" }
        }
    }
}
```

## 7. REST Client 구현

### 7.1 LegacyEsSyncClient

```kotlin
// outbound/client/legacy-es-sync/src/main/kotlin/.../LegacyEsSyncClient.kt
@Component
class LegacyEsSyncClient(
    @Qualifier("legacyEsSyncRestClient") private val restClient: RestClient,
) {
    private val logger by logger()
    private val objectMapper = jacksonObjectMapper()

    /**
     * 레거시 ES pushQueue API 호출
     * @param serviceType PDM 또는 TCMPNY_LINK
     * @param operation CREATE -> POST, UPDATE -> PUT, DELETE -> DELETE
     * @param payload JSON 배열 형태의 데이터
     */
    fun pushQueue(
        serviceType: LegacyServiceType,
        operation: Operation,
        payload: List<Any>,
    ): LegacyEsSyncResponse {
        val httpMethod = when (operation) {
            Operation.CREATE -> HttpMethod.POST
            Operation.UPDATE -> HttpMethod.PUT
            Operation.DELETE -> HttpMethod.DELETE
        }

        return try {
            restClient
                .method(httpMethod)
                .uri("/pushQueue.json?service=${serviceType.paramValue}")
                .contentType(MediaType.APPLICATION_JSON)
                .body(objectMapper.writeValueAsString(payload))
                .retrieve()
                .body(LegacyEsSyncResponse::class.java)
                ?: throw LegacySyncException("Empty response from legacy API")
        } catch (e: Exception) {
            logger.error(e) { "레거시 ES pushQueue 호출 실패: ${e.message}" }
            throw LegacySyncException("Failed to sync to legacy ES", e)
        }
    }
}
```

